export default {"numero":35,"slug":"transparencia-de-ranking","modelo":false,"categoria":"plataforma","titulo":"TRANSPARÊNCIA DE RANKING E RECOMENDAÇÕES","curto":"Transparência de Ranking","versao":"1.0","entradaEmVigor":"14-09-2026","blocos":[{"tipo":"h3","texto":"VENUE1HUB®"},{"tipo":"p","c":[{"t":"Versão:","b":true},{"t":" 1.0\n"},{"t":"Data de entrada em vigor:","b":true},{"t":" 14-09-2026"}]},{"tipo":"p","c":"A presente Política de Transparência de Ranking e Recomendações (“Política”) explica, de forma clara e acessível, os principais fatores que podem influenciar a ordem, seleção, destaque e recomendação de Espaços, Listings, Prestadores, Serviços Complementares e outros conteúdos apresentados através da plataforma Venue1Hub®."},{"tipo":"p","c":"A Venue1Hub procura apresentar resultados relevantes para cada pesquisa, facilitar a descoberta de Espaços adequados e promover um marketplace útil, confiável e transparente."},{"tipo":"p","c":"A ordem em que os resultados são apresentados pode variar em função da pesquisa, filtros selecionados, disponibilidade, características dos Listings, qualidade, desempenho e outros parâmetros descritos nesta Política."},{"tipo":"p","c":"Esta Política aplica-se, conforme relevante, a:"},{"tipo":"lista","chave":"6","itens":[{"n":0,"c":"Clientes;"},{"n":0,"c":"Hosts;"},{"n":0,"c":"Business Hosts;"},{"n":0,"c":"Prestadores;"},{"n":0,"c":"Parceiros;"},{"n":0,"c":"outros utilizadores da Plataforma."}]},{"tipo":"p","c":"Complementa:"},{"tipo":"lista","chave":"5","itens":[{"n":0,"c":"os Termos de Serviço Venue1Hub;"},{"n":0,"c":"os Termos do Cliente / Guest Terms;"},{"n":0,"c":"os Termos do Anfitrião / Host Terms;"},{"n":0,"c":"os Termos para Business Hosts / Anfitriões Profissionais;"},{"n":0,"c":"os Termos de Prestadores / Parceiros;"},{"n":0,"c":"a Política de Anúncios / Listings;"},{"n":0,"c":"a Política de Avaliações e Reviews;"},{"n":0,"c":"os Termos de Subscrição;"},{"n":0,"c":"os Termos de Publicidade / Sponsored Listings;"},{"n":0,"c":"a Política de Conteúdos;"},{"n":0,"c":"a Política Trust & Safety;"},{"n":0,"c":"a Política de Privacidade;"},{"n":0,"c":"as restantes políticas aplicáveis."}]},{"tipo":"h2","texto":"1. IDENTIFICAÇÃO DA PLATAFORMA"},{"tipo":"p","c":"A Venue1Hub® é uma plataforma digital operada pela:"},{"tipo":"p","c":[{"t":"EdgeHub OÜ\n","b":true},{"t":"Sociedade constituída ao abrigo da legislação da República da Estónia\nNúmero de registo: "},{"t":"17515912\n","b":true},{"t":"Sede: Tallinn, Estónia\nE-mail: "},{"t":"mail@venue1hub.com\n","b":true},{"t":"Website:"},{"t":" www.venue1hub.com","href":"http://www.venue1hub.com/"}]},{"tipo":"h2","texto":"2. OBJETIVO"},{"tipo":"p","c":"Esta Política tem como objetivos:"},{"tipo":"p","c":"a) explicar como são ordenados os resultados;"},{"tipo":"p","c":"b) identificar os principais parâmetros que podem influenciar o ranking;"},{"tipo":"p","c":"c) explicar por que motivo certos resultados podem aparecer antes de outros;"},{"tipo":"p","c":"d) distinguir resultados orgânicos de resultados patrocinados;"},{"tipo":"p","c":"e) explicar como filtros e preferências podem alterar os resultados;"},{"tipo":"p","c":"f) proporcionar transparência aos Hosts e Prestadores;"},{"tipo":"p","c":"g) proporcionar maior compreensão aos Clientes;"},{"tipo":"p","c":"h) apoiar o cumprimento das obrigações legais aplicáveis."},{"tipo":"h2","texto":"3. O QUE É RANKING"},{"tipo":"p","c":"Para efeitos desta Política, “ranking” significa a ordem relativa pela qual informações, Listings, Espaços, serviços ou Prestadores são apresentados aos utilizadores."},{"tipo":"p","c":"O ranking poderá existir em:"},{"tipo":"p","c":"a) resultados de pesquisa;"},{"tipo":"p","c":"b) páginas de categorias;"},{"tipo":"p","c":"c) mapas;"},{"tipo":"p","c":"d) recomendações;"},{"tipo":"p","c":"e) páginas de descoberta;"},{"tipo":"p","c":"f) resultados relacionados;"},{"tipo":"p","c":"g) secções de destaque;"},{"tipo":"p","c":"h) outras áreas da Plataforma."},{"tipo":"h2","texto":"4. O QUE É UM SISTEMA DE RECOMENDAÇÃO"},{"tipo":"p","c":"Um sistema de recomendação é um sistema utilizado para sugerir ou priorizar informação apresentada ao utilizador."},{"tipo":"p","c":"Na Venue1Hub, poderá ser utilizado para sugerir, por exemplo:"},{"tipo":"p","c":"a) Espaços;"},{"tipo":"p","c":"b) categorias;"},{"tipo":"p","c":"c) serviços;"},{"tipo":"p","c":"d) Prestadores;"},{"tipo":"p","c":"e) alternativas a uma pesquisa;"},{"tipo":"p","c":"f) resultados relacionados."},{"tipo":"h2","texto":"5. OBJETIVO DO RANKING"},{"tipo":"p","c":"O objetivo principal do ranking é ajudar o utilizador a encontrar opções que sejam, tanto quanto possível:"},{"tipo":"p","c":"a) relevantes para a pesquisa;"},{"tipo":"p","c":"b) disponíveis;"},{"tipo":"p","c":"c) adequadas à localização;"},{"tipo":"p","c":"d) consistentes com os filtros aplicados;"},{"tipo":"p","c":"e) úteis e confiáveis."},{"tipo":"h2","texto":"6. NÃO EXISTE UM ÚNICO RANKING UNIVERSAL"},{"tipo":"p","c":"A Venue1Hub poderá utilizar diferentes lógicas de ordenação consoante:"},{"tipo":"p","c":"a) página;"},{"tipo":"p","c":"b) pesquisa;"},{"tipo":"p","c":"c) categoria;"},{"tipo":"p","c":"d) localização;"},{"tipo":"p","c":"e) filtros;"},{"tipo":"p","c":"f) tipo de utilizador;"},{"tipo":"p","c":"g) funcionalidade."},{"tipo":"p","c":"Por isso, o mesmo Listing poderá aparecer em posições diferentes em pesquisas diferentes."},{"tipo":"h2","texto":"7. PRINCIPAIS PARÂMETROS"},{"tipo":"p","c":"Os principais parâmetros que poderão influenciar o ranking incluem:"},{"tipo":"p","c":"a) relevância;"},{"tipo":"p","c":"b) preço;"},{"tipo":"p","c":"c) reviews;"},{"tipo":"p","c":"d) disponibilidade;"},{"tipo":"p","c":"e) qualidade;"},{"tipo":"p","c":"f) performance;"},{"tipo":"p","c":"g) localização;"},{"tipo":"p","c":"h) conversão;"},{"tipo":"p","c":"i) subscrição;"},{"tipo":"p","c":"j) publicidade ou destaque patrocinado."},{"tipo":"h2","texto":"8. IMPORTÂNCIA RELATIVA DOS PARÂMETROS"},{"tipo":"p","c":"Nem todos os parâmetros terão necessariamente o mesmo peso."},{"tipo":"p","c":"Em geral, parâmetros diretamente relacionados com a intenção de pesquisa do utilizador — como:"},{"tipo":"p","c":"a) relevância;"},{"tipo":"p","c":"b) disponibilidade;"},{"tipo":"p","c":"c) localização;"},{"tipo":"p","c":"d) correspondência com os filtros;"},{"tipo":"p","c":"tendem a possuir importância elevada na determinação dos resultados apresentados."},{"tipo":"p","c":"Outros parâmetros, como qualidade, reviews e performance, poderão ajudar a ordenar resultados que já correspondem aos critérios principais da pesquisa."},{"tipo":"p","c":"Subscrições ou publicidade poderão influenciar determinadas áreas ou mecanismos de visibilidade quando isso seja expressamente previsto e devidamente identificado."},{"tipo":"h2","texto":"9. SEM PERCENTAGENS FIXAS PUBLICADAS"},{"tipo":"p","c":"A Venue1Hub não assume, por esta Política, que cada parâmetro possui uma percentagem fixa e universal."},{"tipo":"p","c":"A ponderação poderá variar consoante:"},{"tipo":"p","c":"a) pesquisa;"},{"tipo":"p","c":"b) filtros;"},{"tipo":"p","c":"c) categoria;"},{"tipo":"p","c":"d) disponibilidade;"},{"tipo":"p","c":"e) mercado;"},{"tipo":"p","c":"f) funcionalidades utilizadas."},{"tipo":"h2","texto":"10. RELEVÂNCIA"},{"tipo":"p","c":"A relevância corresponde ao grau em que um Listing ou serviço corresponde ao que o utilizador procura."},{"tipo":"h2","texto":"11. FATORES DE RELEVÂNCIA"},{"tipo":"p","c":"A relevância poderá considerar elementos como:"},{"tipo":"p","c":"a) categoria do Espaço;"},{"tipo":"p","c":"b) utilização pretendida;"},{"tipo":"p","c":"c) características;"},{"tipo":"p","c":"d) capacidade;"},{"tipo":"p","c":"e) equipamentos;"},{"tipo":"p","c":"f) serviços;"},{"tipo":"p","c":"g) localização;"},{"tipo":"p","c":"h) palavras ou filtros da pesquisa;"},{"tipo":"p","c":"i) outras características estruturadas do Listing."},{"tipo":"h2","texto":"12. EXEMPLO DE RELEVÂNCIA"},{"tipo":"p","c":"Se um utilizador procurar uma:"},{"tipo":"p","c":[{"t":"“sala de formação para 30 pessoas em Coimbra”","b":true}]},{"tipo":"p","c":"poderão ser privilegiados resultados que:"},{"tipo":"p","c":"a) estejam na localização relevante;"},{"tipo":"p","c":"b) permitam formação;"},{"tipo":"p","c":"c) tenham capacidade adequada;"},{"tipo":"p","c":"d) estejam disponíveis na data escolhida."},{"tipo":"h2","texto":"13. CORRESPONDÊNCIA COM FILTROS"},{"tipo":"p","c":"Quando o utilizador seleciona filtros, estes podem ter influência determinante nos resultados."},{"tipo":"h2","texto":"14. EXEMPLOS DE FILTROS"},{"tipo":"p","c":"Os filtros poderão incluir:"},{"tipo":"p","c":"a) localização;"},{"tipo":"p","c":"b) data;"},{"tipo":"p","c":"c) horário;"},{"tipo":"p","c":"d) capacidade;"},{"tipo":"p","c":"e) preço;"},{"tipo":"p","c":"f) tipo de Espaço;"},{"tipo":"p","c":"g) equipamentos;"},{"tipo":"p","c":"h) acessibilidade;"},{"tipo":"p","c":"i) serviços;"},{"tipo":"p","c":"j) características adicionais."},{"tipo":"h2","texto":"15. FILTROS COMO CRITÉRIO DIRETO"},{"tipo":"p","c":"Um Listing que não cumpra um filtro obrigatório selecionado pelo utilizador poderá não ser apresentado."},{"tipo":"h2","texto":"16. LOCALIZAÇÃO"},{"tipo":"p","c":"A localização constitui um parâmetro relevante para pesquisas geográficas."},{"tipo":"h2","texto":"17. PROXIMIDADE"},{"tipo":"p","c":"Quando adequado, a Venue1Hub poderá considerar a proximidade entre:"},{"tipo":"p","c":"a) localização pesquisada;"},{"tipo":"p","c":"b) área pretendida;"},{"tipo":"p","c":"c) localização do Espaço."},{"tipo":"h2","texto":"18. NÃO PRIVILEGIAR SEMPRE O MAIS PRÓXIMO"},{"tipo":"p","c":"O Espaço geograficamente mais próximo não tem necessariamente de aparecer em primeiro lugar."},{"tipo":"p","c":"Outros parâmetros relevantes poderão justificar posição diferente."},{"tipo":"h2","texto":"19. DISPONIBILIDADE"},{"tipo":"p","c":"A disponibilidade é um dos principais fatores do marketplace."},{"tipo":"h2","texto":"20. DATA E HORÁRIO"},{"tipo":"p","c":"Quando o utilizador indique data e horário, a Venue1Hub poderá priorizar Listings que tenham disponibilidade correspondente."},{"tipo":"h2","texto":"21. LISTING INDISPONÍVEL"},{"tipo":"p","c":"Um Listing sem disponibilidade para o período selecionado poderá:"},{"tipo":"p","c":"a) não aparecer;"},{"tipo":"p","c":"b) aparecer com indicação de indisponibilidade;"},{"tipo":"p","c":"c) ser apresentado como alternativa noutra data,"},{"tipo":"p","c":"dependendo da funcionalidade."},{"tipo":"h2","texto":"22. CALENDÁRIO ATUALIZADO"},{"tipo":"p","c":"Manter a disponibilidade atualizada poderá contribuir para uma melhor experiência de pesquisa."},{"tipo":"h2","texto":"23. PREÇO"},{"tipo":"p","c":"O preço poderá influenciar os resultados."},{"tipo":"h2","texto":"24. ORDENAÇÃO POR PREÇO"},{"tipo":"p","c":"Quando o utilizador escolha explicitamente ordenar por preço, esse critério poderá assumir prioridade sobre outros parâmetros."},{"tipo":"h2","texto":"25. FAIXA DE PREÇO"},{"tipo":"p","c":"Listings fora do intervalo de preço selecionado poderão ser excluídos dos resultados."},{"tipo":"h2","texto":"26. PREÇO NÃO É SEMPRE O FATOR PRINCIPAL"},{"tipo":"p","c":"Na ordenação recomendada ou padrão, o Espaço mais barato não tem necessariamente de surgir primeiro."},{"tipo":"h2","texto":"27. PREÇO TOTAL"},{"tipo":"p","c":"Sempre que possível, a lógica de apresentação deverá procurar considerar o preço de forma consistente com a experiência efetiva de contratação."},{"tipo":"h2","texto":"28. REVIEWS"},{"tipo":"p","c":"As avaliações de utilizadores poderão contribuir para o ranking."},{"tipo":"h2","texto":"29. FATORES RELACIONADOS COM REVIEWS"},{"tipo":"p","c":"Poderão ser considerados, entre outros:"},{"tipo":"p","c":"a) classificação média;"},{"tipo":"p","c":"b) número de avaliações;"},{"tipo":"p","c":"c) avaliações recentes;"},{"tipo":"p","c":"d) autenticidade;"},{"tipo":"p","c":"e) consistência da experiência."},{"tipo":"h2","texto":"30. NÃO DEPENDÊNCIA APENAS DA MÉDIA"},{"tipo":"p","c":"Uma classificação média elevada com um número muito reduzido de reviews não tem necessariamente de produzir o mesmo efeito que uma classificação semelhante baseada num histórico mais amplo."},{"tipo":"h2","texto":"31. REVIEWS FRAUDULENTAS"},{"tipo":"p","c":"Reviews removidas por violação da Política de Avaliações e Reviews não deverão contribuir para o ranking."},{"tipo":"h2","texto":"32. QUALIDADE"},{"tipo":"p","c":"A Venue1Hub poderá considerar sinais relacionados com a qualidade do Listing ou da experiência."},{"tipo":"h2","texto":"33. INDICADORES DE QUALIDADE"},{"tipo":"p","c":"Poderão incluir:"},{"tipo":"p","c":"a) completude do Listing;"},{"tipo":"p","c":"b) qualidade da informação;"},{"tipo":"p","c":"c) qualidade das fotografias;"},{"tipo":"p","c":"d) precisão das características anunciadas;"},{"tipo":"p","c":"e) reviews;"},{"tipo":"p","c":"f) informação atualizada;"},{"tipo":"p","c":"g) cumprimento das regras da Plataforma."},{"tipo":"h2","texto":"34. COMPLETUDE DO LISTING"},{"tipo":"p","c":"Um Listing com informação suficiente para permitir ao Cliente compreender adequadamente o Espaço poderá ter melhor desempenho que um Listing muito incompleto."},{"tipo":"h2","texto":"35. FOTOGRAFIAS"},{"tipo":"p","c":"Fotografias claras, relevantes e representativas poderão contribuir para a qualidade do Listing e para a experiência do utilizador."},{"tipo":"h2","texto":"36. INFORMAÇÃO FALSA"},{"tipo":"p","c":"A utilização de informação falsa ou enganadora não é uma forma legítima de melhorar ranking."},{"tipo":"p","c":"Poderá resultar em:"},{"tipo":"p","c":"a) correção;"},{"tipo":"p","c":"b) redução de visibilidade;"},{"tipo":"p","c":"c) suspensão do Listing;"},{"tipo":"p","c":"d) outras medidas previstas nas políticas aplicáveis."},{"tipo":"h2","texto":"37. PERFORMANCE"},{"tipo":"p","c":"A performance do Host ou Listing poderá ser considerada."},{"tipo":"h2","texto":"38. INDICADORES DE PERFORMANCE"},{"tipo":"p","c":"Poderão incluir, por exemplo:"},{"tipo":"p","c":"a) capacidade de concluir Reservas;"},{"tipo":"p","c":"b) taxa de cancelamento;"},{"tipo":"p","c":"c) tempo de resposta;"},{"tipo":"p","c":"d) confiabilidade;"},{"tipo":"p","c":"e) problemas de disponibilidade;"},{"tipo":"p","c":"f) experiência dos Clientes;"},{"tipo":"p","c":"g) outros indicadores operacionais."},{"tipo":"h2","texto":"39. CANCELAMENTOS"},{"tipo":"p","c":"Cancelamentos imputáveis ao Host poderão afetar a performance do Listing quando sejam relevantes e repetidos."},{"tipo":"h2","texto":"40. TEMPO DE RESPOSTA"},{"tipo":"p","c":"A rapidez e consistência com que o Host responde a pedidos poderá constituir um sinal de qualidade operacional."},{"tipo":"h2","texto":"41. NÃO PENALIZAÇÃO POR CAUSAS LEGÍTIMAS"},{"tipo":"p","c":"A Venue1Hub poderá procurar distinguir cancelamentos ou problemas imputáveis ao Host de situações justificadas ou extraordinárias."},{"tipo":"h2","texto":"42. CONVERSÃO"},{"tipo":"p","c":"A conversão poderá ser utilizada como um dos sinais de utilidade de determinado Listing."},{"tipo":"h2","texto":"43. O QUE SIGNIFICA CONVERSÃO"},{"tipo":"p","c":"Conversão poderá refletir, por exemplo, a relação entre:"},{"tipo":"p","c":"a) visualizações;"},{"tipo":"p","c":"b) interesse;"},{"tipo":"p","c":"c) pedidos;"},{"tipo":"p","c":"d) Reservas;"},{"tipo":"p","c":"e) contratações concluídas."},{"tipo":"h2","texto":"44. CONVERSÃO NÃO É UM DIREITO ADQUIRIDO"},{"tipo":"p","c":"Um Listing com bom histórico de conversão não tem direito permanente a determinada posição."},{"tipo":"h2","texto":"45. NOVOS LISTINGS"},{"tipo":"p","c":"A Venue1Hub poderá adotar mecanismos que permitam a novos Listings obter visibilidade suficiente para desenvolver histórico."},{"tipo":"h2","texto":"46. NÃO EXCLUSÃO AUTOMÁTICA DE NOVOS HOSTS"},{"tipo":"p","c":"A inexistência de histórico não significa necessariamente que um novo Listing aparecerá sempre no final dos resultados."},{"tipo":"h2","texto":"47. CONFIABILIDADE"},{"tipo":"p","c":"Sinais relacionados com a confiabilidade do Host poderão ser considerados em determinadas funcionalidades."},{"tipo":"h2","texto":"48. VERIFICAÇÃO"},{"tipo":"p","c":"O estado de determinados processos de verificação poderá ser relevante quando essa utilização seja legítima e esteja integrada na lógica do produto."},{"tipo":"h2","texto":"49. VERIFICAÇÃO NÃO GARANTE PRIMEIRA POSIÇÃO"},{"tipo":"p","c":"Uma Conta verificada não recebe automaticamente a primeira posição."},{"tipo":"h2","texto":"50. VENUE1HUB® VERIFIED"},{"tipo":"p","c":"Se futuramente existir um programa Venue1Hub® Verified, a respetiva influência sobre ranking deverá ser explicada quando implementada."},{"tipo":"h2","texto":"51. ACESSIBILIDADE"},{"tipo":"p","c":"As características de acessibilidade poderão influenciar resultados quando o utilizador procure ou filtre especificamente por essas características."},{"tipo":"h2","texto":"52. FILTROS DE ACESSIBILIDADE"},{"tipo":"p","c":"Por exemplo, um utilizador que selecione:"},{"tipo":"p","c":[{"t":"entrada sem degraus","b":true}]},{"tipo":"p","c":"poderá receber prioritariamente resultados declarados como correspondentes a essa característica."},{"tipo":"h2","texto":"53. SUBSCRIÇÕES"},{"tipo":"p","c":"Determinados planos de subscrição poderão oferecer vantagens de visibilidade quando isso esteja expressamente incluído nas condições do plano."},{"tipo":"h2","texto":"54. PLANO PRO"},{"tipo":"p","c":"O Plano de Negócios da Venue1Hub prevê para o Plano Pro funcionalidades como:"},{"tipo":"p","c":"a) maior visibilidade;"},{"tipo":"p","c":"b) destaque básico ou moderado;"},{"tipo":"p","c":"c) outras funcionalidades comerciais."},{"tipo":"p","c":"As condições concretas aplicáveis serão as publicadas no plano em vigor."},{"tipo":"h2","texto":"55. PLANO BUSINESS"},{"tipo":"p","c":"O Plano Business poderá incluir ferramentas comerciais adicionais, mas não confere automaticamente direito permanente a determinada posição nos resultados."},{"tipo":"h2","texto":"56. ENTERPRISE"},{"tipo":"p","c":"Condições Enterprise poderão incluir funcionalidades específicas de visibilidade ou integração quando expressamente contratadas."},{"tipo":"h2","texto":"57. EFEITO DA SUBSCRIÇÃO"},{"tipo":"p","c":"Quando uma subscrição paga influencie o ranking ou visibilidade, essa influência deverá ser transparente."},{"tipo":"h2","texto":"58. NÃO OCULTAÇÃO DE INFLUÊNCIA COMERCIAL"},{"tipo":"p","c":"A Venue1Hub não deverá apresentar como puramente orgânico um posicionamento que resulte diretamente de pagamento para obter destaque."},{"tipo":"h2","texto":"59. PUBLICIDADE"},{"tipo":"p","c":"A Venue1Hub poderá disponibilizar produtos publicitários ou resultados patrocinados."},{"tipo":"h2","texto":"60. SPONSORED LISTINGS"},{"tipo":"p","c":"Um Host ou Prestador poderá, quando a funcionalidade exista, contratar maior exposição através de Sponsored Listings ou produtos semelhantes."},{"tipo":"h2","texto":"61. IDENTIFICAÇÃO"},{"tipo":"p","c":"Resultados patrocinados deverão ser claramente identificados como tal."},{"tipo":"p","c":"Poderão utilizar designações como:"},{"tipo":"p","c":[{"t":"Patrocinado","b":true}]},{"tipo":"p","c":[{"t":"Sponsored","b":true}]},{"tipo":"p","c":[{"t":"Anúncio","b":true}]},{"tipo":"p","c":"ou outra indicação clara e adequada."},{"tipo":"h2","texto":"62. PUBLICIDADE NÃO DEVE PARECER ORGÂNICA"},{"tipo":"p","c":"A apresentação deverá permitir ao utilizador compreender quando determinada posição resulta de uma relação comercial ou pagamento."},{"tipo":"h2","texto":"63. PAGAMENTO E RANKING"},{"tipo":"p","c":"Quando a remuneração paga à Venue1Hub possa influenciar a posição ou destaque, a Plataforma deverá explicar essa possibilidade."},{"tipo":"h2","texto":"64. DESTAQUE NÃO GARANTE RESERVA"},{"tipo":"p","c":"A aquisição de publicidade ou destaque não garante:"},{"tipo":"p","c":"a) cliques;"},{"tipo":"p","c":"b) contactos;"},{"tipo":"p","c":"c) Reservas;"},{"tipo":"p","c":"d) receita;"},{"tipo":"p","c":"e) determinada taxa de conversão."},{"tipo":"h2","texto":"65. RESULTADOS PATROCINADOS E ELEGIBILIDADE"},{"tipo":"p","c":"A Venue1Hub poderá exigir que um Listing cumpra determinados requisitos mínimos para participar em produtos patrocinados."},{"tipo":"h2","texto":"66. PAGAMENTO NÃO ELIMINA REGRAS DE QUALIDADE"},{"tipo":"p","c":"Um Host não poderá comprar o direito de manter um Listing ilegal, falso, suspenso ou incompatível com as políticas da Plataforma."},{"tipo":"h2","texto":"67. SUSPENSÃO DE LISTING PATROCINADO"},{"tipo":"p","c":"Se um Listing patrocinado for suspenso por razões de segurança, compliance ou conteúdo, o estatuto patrocinado não impede a aplicação da medida."},{"tipo":"h2","texto":"68. ORDENAR POR OPÇÕES ESCOLHIDAS PELO UTILIZADOR"},{"tipo":"p","c":"A Venue1Hub poderá permitir diferentes opções de ordenação."},{"tipo":"h2","texto":"69. EXEMPLOS DE ORDENAÇÃO"},{"tipo":"p","c":"Poderão existir opções como:"},{"tipo":"p","c":"a) recomendados;"},{"tipo":"p","c":"b) preço mais baixo;"},{"tipo":"p","c":"c) preço mais alto;"},{"tipo":"p","c":"d) melhor avaliados;"},{"tipo":"p","c":"e) proximidade;"},{"tipo":"p","c":"f) outros critérios."},{"tipo":"h2","texto":"70. EFEITO DA ESCOLHA"},{"tipo":"p","c":"Quando o utilizador seleciona uma opção específica, essa escolha poderá alterar substancialmente a ordem dos resultados."},{"tipo":"h2","texto":"71. RECOMENDADO / RELEVANTE"},{"tipo":"p","c":"Quando a opção seja “Recomendado”, a Venue1Hub poderá combinar vários parâmetros descritos nesta Política."},{"tipo":"h2","texto":"72. PESQUISA POR MAPA"},{"tipo":"p","c":"Resultados apresentados num mapa poderão depender adicionalmente:"},{"tipo":"p","c":"a) da área visualizada;"},{"tipo":"p","c":"b) do nível de zoom;"},{"tipo":"p","c":"c) da disponibilidade nessa área;"},{"tipo":"p","c":"d) de outros critérios relevantes."},{"tipo":"h2","texto":"73. CATEGORIAS"},{"tipo":"p","c":"Resultados numa página de categoria poderão ser classificados segundo critérios adequados àquela categoria."},{"tipo":"h2","texto":"74. SERVIÇOS COMPLEMENTARES"},{"tipo":"p","c":"Prestadores de Serviços Complementares poderão igualmente ser ordenados através de parâmetros como:"},{"tipo":"p","c":"a) relevância;"},{"tipo":"p","c":"b) localização;"},{"tipo":"p","c":"c) disponibilidade;"},{"tipo":"p","c":"d) preço;"},{"tipo":"p","c":"e) reviews;"},{"tipo":"p","c":"f) qualidade;"},{"tipo":"p","c":"g) performance;"},{"tipo":"p","c":"h) destaque comercial."},{"tipo":"h2","texto":"75. PARCEIROS CERTIFICADOS"},{"tipo":"p","c":"Um eventual estatuto de Parceiro Certificado poderá ser apresentado ao utilizador e poderá ser considerado em determinadas funcionalidades de recomendação, quando isso esteja previsto no produto."},{"tipo":"h2","texto":"76. CERTIFICAÇÃO NÃO GARANTE POSIÇÃO"},{"tipo":"p","c":"A certificação não significa direito permanente a uma posição específica."},{"tipo":"h2","texto":"77. PERSONALIZAÇÃO"},{"tipo":"p","c":"A Venue1Hub poderá futuramente utilizar determinados sinais para personalizar recomendações."},{"tipo":"h2","texto":"78. EXEMPLOS DE PERSONALIZAÇÃO"},{"tipo":"p","c":"Poderão ser consideradas, conforme legalmente permitido:"},{"tipo":"p","c":"a) pesquisas anteriores;"},{"tipo":"p","c":"b) categorias consultadas;"},{"tipo":"p","c":"c) localização selecionada;"},{"tipo":"p","c":"d) filtros;"},{"tipo":"p","c":"e) Reservas anteriores;"},{"tipo":"p","c":"f) preferências indicadas pelo utilizador."},{"tipo":"h2","texto":"79. PROTEÇÃO DE DADOS"},{"tipo":"p","c":"Qualquer personalização baseada em dados pessoais será realizada de acordo com:"},{"tipo":"p","c":"a) Política de Privacidade;"},{"tipo":"p","c":"b) legislação aplicável;"},{"tipo":"p","c":"c) configurações e direitos do utilizador."},{"tipo":"h2","texto":"80. NÃO UTILIZAÇÃO INDISCRIMINADA DE DADOS"},{"tipo":"p","c":"A existência de dados sobre um utilizador não significa que todos sejam utilizados para ranking ou recomendação."},{"tipo":"h2","texto":"81. CATEGORIAS ESPECIAIS DE DADOS"},{"tipo":"p","c":"A Venue1Hub não deverá utilizar categorias especiais de dados pessoais para personalização publicitária quando tal seja proibido pela legislação aplicável."},{"tipo":"h2","texto":"82. IA E RECOMENDAÇÕES"},{"tipo":"p","c":"O Plano de Negócios prevê, numa fase futura de evolução tecnológica, a introdução de inteligência artificial aplicada à recomendação de Espaços."},{"tipo":"h2","texto":"83. IA NÃO ESTÁ PRESUMIDA NO LANÇAMENTO"},{"tipo":"p","c":"A existência dessa previsão estratégica não significa que as recomendações iniciais da Venue1Hub utilizem necessariamente inteligência artificial."},{"tipo":"p","c":"A política deverá ser atualizada quando essas funcionalidades forem efetivamente implementadas."},{"tipo":"h2","texto":"84. FUTURAS RECOMENDAÇÕES POR IA"},{"tipo":"p","c":"Quando sejam implementadas, poderão analisar parâmetros adequados para sugerir Espaços potencialmente relevantes."},{"tipo":"h2","texto":"85. TRANSPARÊNCIA DA IA"},{"tipo":"p","c":"A utilização de IA não elimina as obrigações de explicar os principais fatores relevantes do sistema de recomendação quando legalmente exigido."},{"tipo":"h2","texto":"86. PRICING DINÂMICO"},{"tipo":"p","c":"O Plano de Negócios prevê igualmente pricing dinâmico numa fase futura."},{"tipo":"p","c":"A existência desta previsão não significa que o ranking atualmente utilize pricing dinâmico."},{"tipo":"h2","texto":"87. DISTINÇÃO ENTRE PREÇO E RANKING"},{"tipo":"p","c":"O mecanismo utilizado para determinar um preço é distinto do mecanismo utilizado para ordenar Listings, ainda que o preço final possa posteriormente constituir um parâmetro de pesquisa ou ranking."},{"tipo":"h2","texto":"88. TESTES E OTIMIZAÇÃO"},{"tipo":"p","c":"A Venue1Hub poderá realizar testes destinados a melhorar:"},{"tipo":"p","c":"a) pesquisa;"},{"tipo":"p","c":"b) relevância;"},{"tipo":"p","c":"c) conversão;"},{"tipo":"p","c":"d) experiência;"},{"tipo":"p","c":"e) qualidade das recomendações."},{"tipo":"h2","texto":"89. A/B TESTING"},{"tipo":"p","c":"Determinados utilizadores poderão temporariamente visualizar versões diferentes de uma funcionalidade durante testes legítimos de produto."},{"tipo":"h2","texto":"90. TESTES NÃO DEVEM CONTORNAR OBRIGAÇÕES DE TRANSPARÊNCIA"},{"tipo":"p","c":"A utilização de testes não elimina as obrigações legais aplicáveis a ranking, publicidade ou recomendações."},{"tipo":"h2","texto":"91. QUALIDADE DO MARKETPLACE"},{"tipo":"p","c":"A Venue1Hub poderá ajustar mecanismos de ranking para promover:"},{"tipo":"p","c":"a) informação confiável;"},{"tipo":"p","c":"b) disponibilidade real;"},{"tipo":"p","c":"c) qualidade;"},{"tipo":"p","c":"d) boa experiência;"},{"tipo":"p","c":"e) integridade do marketplace."},{"tipo":"h2","texto":"92. FRAUDE E MANIPULAÇÃO"},{"tipo":"p","c":"A Venue1Hub poderá reduzir ou remover a influência de sinais manipulados."},{"tipo":"h2","texto":"93. MANIPULAÇÃO DE RANKING"},{"tipo":"p","c":"É proibido tentar manipular artificialmente o ranking."},{"tipo":"h2","texto":"94. EXEMPLOS DE MANIPULAÇÃO"},{"tipo":"p","c":"Poderão constituir manipulação:"},{"tipo":"p","c":"a) Reservas fictícias;"},{"tipo":"p","c":"b) reviews falsas;"},{"tipo":"p","c":"c) contas falsas;"},{"tipo":"p","c":"d) cliques artificiais;"},{"tipo":"p","c":"e) tráfego automatizado;"},{"tipo":"p","c":"f) alteração enganadora de dados;"},{"tipo":"p","c":"g) outras técnicas destinadas a falsear performance."},{"tipo":"h2","texto":"95. CONSEQUÊNCIAS"},{"tipo":"p","c":"Manipulação confirmada poderá levar a:"},{"tipo":"p","c":"a) remoção dos sinais falsos;"},{"tipo":"p","c":"b) perda de visibilidade;"},{"tipo":"p","c":"c) suspensão do Listing;"},{"tipo":"p","c":"d) suspensão da Conta;"},{"tipo":"p","c":"e) outras medidas aplicáveis."},{"tipo":"h2","texto":"96. NÃO GARANTIA DE POSIÇÃO"},{"tipo":"p","c":"Nenhum Host ou Prestador possui direito adquirido a:"},{"tipo":"p","c":"a) primeira posição;"},{"tipo":"p","c":"b) primeira página;"},{"tipo":"p","c":"c) determinado número de impressões;"},{"tipo":"p","c":"d) determinada posição média;"},{"tipo":"p","c":"e) volume específico de tráfego."},{"tipo":"h2","texto":"97. VARIAÇÃO DO RANKING"},{"tipo":"p","c":"A posição poderá mudar por razões legítimas como:"},{"tipo":"p","c":"a) novos Listings;"},{"tipo":"p","c":"b) alterações de disponibilidade;"},{"tipo":"p","c":"c) preço;"},{"tipo":"p","c":"d) reviews;"},{"tipo":"p","c":"e) performance;"},{"tipo":"p","c":"f) filtros;"},{"tipo":"p","c":"g) localização;"},{"tipo":"p","c":"h) alterações de produto;"},{"tipo":"p","c":"i) comportamento do marketplace."},{"tipo":"h2","texto":"98. ALTERAÇÃO PELO HOST"},{"tipo":"p","c":"Alterações realizadas pelo próprio Host podem afetar a posição."},{"tipo":"h2","texto":"99. EXEMPLOS"},{"tipo":"p","c":"Podem influenciar o ranking:"},{"tipo":"p","c":"a) alterar preço;"},{"tipo":"p","c":"b) fechar datas;"},{"tipo":"p","c":"c) adicionar características;"},{"tipo":"p","c":"d) atualizar descrição;"},{"tipo":"p","c":"e) mudar localização incorretamente;"},{"tipo":"p","c":"f) receber novas reviews."},{"tipo":"h2","texto":"100. NÃO GARANTIA DE EFEITO"},{"tipo":"p","c":"Uma melhoria num parâmetro não significa necessariamente aumento de posição, porque o ranking combina vários fatores."},{"tipo":"h2","texto":"101. INFORMAÇÃO PARA BUSINESS HOSTS"},{"tipo":"p","c":"Business Hosts devem conseguir compreender os principais fatores que influenciam a visibilidade das suas ofertas."},{"tipo":"h2","texto":"102. IMPORTÂNCIA RELATIVA PARA BUSINESS HOSTS"},{"tipo":"p","c":"De forma geral:"},{"tipo":"p","c":[{"t":"Muito relevantes para correspondência da pesquisa:","b":true}]},{"tipo":"lista","chave":"2","itens":[{"n":0,"c":"relevância;"},{"n":0,"c":"disponibilidade;"},{"n":0,"c":"localização;"},{"n":0,"c":"filtros selecionados."}]},{"tipo":"p","c":[{"t":"Relevantes para diferenciação entre resultados elegíveis:","b":true}]},{"tipo":"lista","chave":"1","itens":[{"n":0,"c":"qualidade;"},{"n":0,"c":"reviews;"},{"n":0,"c":"performance;"},{"n":0,"c":"preço;"},{"n":0,"c":"conversão."}]},{"tipo":"p","c":[{"t":"Podem criar visibilidade adicional quando contratualmente previsto:","b":true}]},{"tipo":"lista","chave":"3","itens":[{"n":0,"c":"subscrição;"},{"n":0,"c":"publicidade;"},{"n":0,"c":"Sponsored Listings."}]},{"tipo":"p","c":"Esta descrição é qualitativa e não corresponde a uma fórmula matemática fixa."},{"tipo":"h2","texto":"103. SEGREDOS COMERCIAIS E INTEGRIDADE"},{"tipo":"p","c":"A transparência sobre ranking não exige a divulgação pública de:"},{"tipo":"p","c":"a) código-fonte;"},{"tipo":"p","c":"b) fórmula completa;"},{"tipo":"p","c":"c) pesos exatos quando a sua divulgação não seja legalmente necessária;"},{"tipo":"p","c":"d) regras antifraude;"},{"tipo":"p","c":"e) thresholds de segurança;"},{"tipo":"p","c":"f) informação que permita manipular o sistema."},{"tipo":"h2","texto":"104. EQUILÍBRIO ENTRE TRANSPARÊNCIA E SEGURANÇA"},{"tipo":"p","c":"A Venue1Hub procurará fornecer informação suficiente para permitir uma compreensão real do sistema sem facilitar:"},{"tipo":"p","c":"a) fraude;"},{"tipo":"p","c":"b) gaming;"},{"tipo":"p","c":"c) manipulação;"},{"tipo":"p","c":"d) abuso."},{"tipo":"h2","texto":"105. ALTERAÇÕES AO RANKING"},{"tipo":"p","c":"A Venue1Hub poderá alterar os mecanismos de ranking."},{"tipo":"h2","texto":"106. RAZÕES PARA ALTERAÇÃO"},{"tipo":"p","c":"Poderão incluir:"},{"tipo":"p","c":"a) melhoria da relevância;"},{"tipo":"p","c":"b) experiência do utilizador;"},{"tipo":"p","c":"c) prevenção de fraude;"},{"tipo":"p","c":"d) evolução do marketplace;"},{"tipo":"p","c":"e) novas funcionalidades;"},{"tipo":"p","c":"f) alterações legais;"},{"tipo":"p","c":"g) novos mercados."},{"tipo":"h2","texto":"107. ALTERAÇÕES MATERIAIS"},{"tipo":"p","c":"Quando alterações materiais afetem significativamente os principais parâmetros e exista obrigação de atualização ou comunicação, esta Política será atualizada de forma adequada."},{"tipo":"h2","texto":"108. DOCUMENTAÇÃO INTERNA"},{"tipo":"p","c":"A Venue1Hub deverá manter documentação interna sobre o funcionamento dos sistemas de ranking e recomendação."},{"tipo":"p","c":[{"t":"O guia jurídico inclui expressamente "},{"t":"Ranking documentation","b":true},{"t":" no Legal Operations Pack."}]},{"tipo":"h2","texto":"109. DOCUMENTAÇÃO DO ALGORITMO"},{"tipo":"p","c":"A documentação interna deverá permitir compreender:"},{"tipo":"p","c":"a) finalidade;"},{"tipo":"p","c":"b) parâmetros;"},{"tipo":"p","c":"c) importância relativa;"},{"tipo":"p","c":"d) alterações;"},{"tipo":"p","c":"e) responsáveis;"},{"tipo":"p","c":"f) testes;"},{"tipo":"p","c":"g) influência comercial;"},{"tipo":"p","c":"h) controles contra manipulação."},{"tipo":"h2","texto":"110. VERSIONAMENTO DO RANKING"},{"tipo":"p","c":"Alterações materiais aos principais mecanismos deverão, quando adequado, ser versionadas internamente."},{"tipo":"h2","texto":"111. RANKING VERSION ID"},{"tipo":"p","c":"A Venue1Hub poderá utilizar identificadores internos para versões relevantes do sistema."},{"tipo":"p","c":"Exemplo:"},{"tipo":"p","c":[{"t":"RANK-V1H-[ANO]-[VERSÃO]","b":true}]},{"tipo":"h2","texto":"112. AUDITABILIDADE"},{"tipo":"p","c":"Sempre que possível, a arquitetura deve permitir explicar porque determinado conjunto de resultados foi apresentado com base nos parâmetros existentes naquele momento."},{"tipo":"h2","texto":"113. NÃO NECESSIDADE DE RECONSTRUÇÃO PERFEITA DE CADA PESQUISA"},{"tipo":"p","c":"A auditabilidade não significa necessariamente conservar para sempre cada resultado individual apresentado a cada utilizador."},{"tipo":"p","c":"Os períodos e níveis de logging deverão respeitar necessidade, proporcionalidade e proteção de dados."},{"tipo":"h2","texto":"114. MONITORIZAÇÃO"},{"tipo":"p","c":"A Venue1Hub poderá acompanhar indicadores como:"},{"tipo":"p","c":"a) qualidade dos resultados;"},{"tipo":"p","c":"b) conversão;"},{"tipo":"p","c":"c) cancelamentos;"},{"tipo":"p","c":"d) disponibilidade;"},{"tipo":"p","c":"e) reviews;"},{"tipo":"p","c":"f) cliques;"},{"tipo":"p","c":"g) Reservas;"},{"tipo":"p","c":"h) outros indicadores adequados."},{"tipo":"h2","texto":"115. BUSINESS INTELLIGENCE"},{"tipo":"p","c":"O Plano de Negócios prevê a utilização de Business Intelligence para acompanhar oferta, procura, volume transacionado, receita, tempo de resposta, cancelamentos e satisfação, com o objetivo de otimizar continuamente o marketplace."},{"tipo":"h2","texto":"116. UTILIZAÇÃO DE MÉTRICAS"},{"tipo":"p","c":"A utilização dessas métricas para otimização não significa necessariamente que todas sejam utilizadas diretamente como parâmetros de ranking."},{"tipo":"h2","texto":"117. RANKING E SEGURANÇA"},{"tipo":"p","c":"A Venue1Hub poderá limitar visibilidade de Listings que estejam:"},{"tipo":"p","c":"a) em investigação;"},{"tipo":"p","c":"b) suspensos;"},{"tipo":"p","c":"c) sujeitos a problema de segurança;"},{"tipo":"p","c":"d) não conformes;"},{"tipo":"p","c":"e) indisponíveis."},{"tipo":"h2","texto":"118. PAUSA DE LISTING"},{"tipo":"p","c":"Um Listing pausado não deverá normalmente aparecer como disponível para nova Reserva."},{"tipo":"h2","texto":"119. SUSPENSÃO"},{"tipo":"p","c":"Um Listing suspenso poderá ser removido dos resultados enquanto a medida estiver em vigor."},{"tipo":"h2","texto":"120. RESTRIÇÃO NÃO É NECESSARIAMENTE “PENALIZAÇÃO DE RANKING”"},{"tipo":"p","c":"Certas ofertas podem deixar de ser apresentadas porque não são elegíveis para publicação, e não porque receberam simplesmente um score inferior."},{"tipo":"h2","texto":"121. NOTICE & ACTION"},{"tipo":"p","c":"Conteúdo ou Listing removido ao abrigo do Procedimento Notice & Action deixará de participar normalmente no ranking enquanto estiver indisponível."},{"tipo":"h2","texto":"122. REVIEWS REMOVIDAS"},{"tipo":"p","c":"Reviews removidas nos termos das políticas aplicáveis não deverão continuar a influenciar artificialmente o ranking."},{"tipo":"h2","texto":"123. CANCELAMENTOS POR CIRCUNSTÂNCIAS EXTRAORDINÁRIAS"},{"tipo":"p","c":"A Venue1Hub poderá procurar distinguir eventos extraordinários legítimos de cancelamentos imputáveis ao Host ao avaliar performance."},{"tipo":"h2","texto":"124. NÃO DISCRIMINAÇÃO"},{"tipo":"p","c":"Os sistemas de ranking não deverão ser desenhados com a finalidade de discriminar ilegalmente utilizadores."},{"tipo":"h2","texto":"125. LOCALIZAÇÃO NÃO É ATRIBUTO PESSOAL"},{"tipo":"p","c":"A utilização da localização do Espaço como parâmetro de pesquisa geográfica é inerente à natureza do marketplace e distingue-se da utilização de características pessoais protegidas."},{"tipo":"h2","texto":"126. DADOS PESSOAIS E RANKING"},{"tipo":"p","c":"Quando dados pessoais sejam utilizados para personalização, aplicam-se a Política de Privacidade e a legislação de proteção de dados."},{"tipo":"h2","texto":"127. CONTROLO DO UTILIZADOR"},{"tipo":"p","c":"Quando a Plataforma disponibilize opções que permitam ao utilizador modificar a forma de ordenação ou recomendação, essas opções serão apresentadas na interface correspondente."},{"tipo":"h2","texto":"128. ALTERAÇÃO DE ORDENAÇÃO"},{"tipo":"p","c":"O utilizador poderá, quando disponível, alterar de:"},{"tipo":"p","c":[{"t":"Recomendados","b":true}]},{"tipo":"p","c":"para, por exemplo:"},{"tipo":"p","c":[{"t":"Preço","b":true}]},{"tipo":"p","c":[{"t":"Avaliação","b":true}]},{"tipo":"p","c":[{"t":"Distância","b":true}]},{"tipo":"p","c":"ou outras opções disponibilizadas."},{"tipo":"h2","texto":"129. EFEITO DOS FILTROS"},{"tipo":"p","c":"A seleção ou remoção de filtros constitui igualmente uma forma de o utilizador influenciar os resultados."},{"tipo":"h2","texto":"130. REPOSIÇÃO DE FILTROS"},{"tipo":"p","c":"A remoção dos filtros poderá voltar a apresentar um conjunto mais amplo de resultados."},{"tipo":"h2","texto":"131. RESULTADOS SEM CORRESPONDÊNCIA EXATA"},{"tipo":"p","c":"Quando não existam resultados que correspondam integralmente à pesquisa, a Venue1Hub poderá apresentar alternativas."},{"tipo":"h2","texto":"132. ALTERNATIVAS"},{"tipo":"p","c":"Estas poderão incluir:"},{"tipo":"p","c":"a) localidades próximas;"},{"tipo":"p","c":"b) outras datas;"},{"tipo":"p","c":"c) categorias semelhantes;"},{"tipo":"p","c":"d) opções de preço diferente;"},{"tipo":"p","c":"e) outros Espaços potencialmente relevantes."},{"tipo":"h2","texto":"133. IDENTIFICAÇÃO DE ALTERNATIVAS"},{"tipo":"p","c":"Sempre que adequado, deverá ser claro que determinados resultados são alternativas e não correspondências exatas."},{"tipo":"h2","texto":"134. DISPONIBILIDADE DE OPÇÕES"},{"tipo":"p","c":"Nem todas as opções de ordenação ou personalização estarão necessariamente disponíveis desde o lançamento."},{"tipo":"h2","texto":"135. DESENVOLVIMENTO FASEADO"},{"tipo":"p","c":"O Plano de Negócios prevê evolução tecnológica faseada: funcionalidades iniciais de marketplace, Reservas, pagamentos e perfis, evoluindo posteriormente para dashboards, Business Intelligence e, numa fase global, IA aplicada à recomendação."},{"tipo":"h2","texto":"136. A POLÍTICA DEVE REFLETIR O PRODUTO REAL"},{"tipo":"p","c":"A Venue1Hub atualizará esta Política à medida que novas funcionalidades de ranking e recomendação forem efetivamente ativadas."},{"tipo":"p","c":"Não deverão ser descritos como operacionais mecanismos que existam apenas no roadmap."},{"tipo":"h2","texto":"137. PUBLICIDADE E RANKING SÃO DISTINTOS"},{"tipo":"p","c":"A Venue1Hub deverá distinguir:"},{"tipo":"p","c":[{"t":"Ranking orgânico","b":true}]},{"tipo":"p","c":"de"},{"tipo":"p","c":[{"t":"Posicionamento patrocinado","b":true},{"t":"."}]},{"tipo":"h2","texto":"138. RANKING ORGÂNICO"},{"tipo":"p","c":"O ranking orgânico resulta dos parâmetros de pesquisa, relevância, qualidade, disponibilidade e outros fatores não exclusivamente determinados por pagamento publicitário."},{"tipo":"h2","texto":"139. POSICIONAMENTO PATROCINADO"},{"tipo":"p","c":"O posicionamento patrocinado resulta, total ou parcialmente, de uma relação comercial destinada a obter maior visibilidade."},{"tipo":"h2","texto":"140. RESULTADO PAGO DEVE SER IDENTIFICADO"},{"tipo":"p","c":"Sempre que um pagamento tenha como efeito a apresentação publicitária ou promoção específica de determinado resultado, essa natureza deverá ser identificável pelo utilizador."},{"tipo":"h2","texto":"141. TERMOS DE PUBLICIDADE"},{"tipo":"p","c":"As regras detalhadas de:"},{"tipo":"p","c":"a) campanhas;"},{"tipo":"p","c":"b) publicidade;"},{"tipo":"p","c":"c) Sponsored Listings;"},{"tipo":"p","c":"d) compra de visibilidade;"},{"tipo":"p","c":"serão tratadas nos Termos de Publicidade / Sponsored Listings."},{"tipo":"h2","texto":"142. SUBSCRIÇÃO NÃO É NECESSARIAMENTE PUBLICIDADE"},{"tipo":"p","c":"Uma subscrição poderá incluir funcionalidades adicionais de visibilidade sem que todos os resultados do subscritor sejam necessariamente anúncios."},{"tipo":"p","c":"A influência concreta do plano deverá ser descrita nas respetivas condições."},{"tipo":"h2","texto":"143. NÃO MISTURAR VANTAGENS COMERCIAIS OCULTAS"},{"tipo":"p","c":"A Venue1Hub deverá evitar mecanismos em que um Host pague para influenciar materialmente o ranking sem que essa possibilidade esteja prevista e explicada."},{"tipo":"h2","texto":"144. RESPONSABILIDADE DO HOST"},{"tipo":"p","c":"Hosts podem melhorar legitimamente a qualidade da sua presença através de:"},{"tipo":"p","c":"a) informação completa;"},{"tipo":"p","c":"b) calendário atualizado;"},{"tipo":"p","c":"c) preços transparentes;"},{"tipo":"p","c":"d) boa qualidade de serviço;"},{"tipo":"p","c":"e) respostas adequadas;"},{"tipo":"p","c":"f) redução de cancelamentos evitáveis;"},{"tipo":"p","c":"g) boas experiências dos Clientes."},{"tipo":"h2","texto":"145. NÃO PROMETER MELHORIA ESPECÍFICA"},{"tipo":"p","c":"A Venue1Hub não garante que determinada ação gere uma posição específica."},{"tipo":"h2","texto":"146. RECOMENDAÇÕES DE OTIMIZAÇÃO"},{"tipo":"p","c":"A Plataforma poderá fornecer sugestões aos Hosts sobre como melhorar:"},{"tipo":"p","c":"a) Listing;"},{"tipo":"p","c":"b) fotografia;"},{"tipo":"p","c":"c) disponibilidade;"},{"tipo":"p","c":"d) preço;"},{"tipo":"p","c":"e) informação;"},{"tipo":"p","c":"f) qualidade operacional."},{"tipo":"h2","texto":"147. SUGESTÕES NÃO ALTERAM REGRAS"},{"tipo":"p","c":"Essas sugestões não significam que a Venue1Hub esteja obrigada a atribuir uma determinada posição após serem seguidas."},{"tipo":"h2","texto":"148. PERFORMANCE DO PRESTADOR"},{"tipo":"p","c":"Prestadores de Serviços Complementares poderão igualmente receber recomendações destinadas a melhorar a qualidade do perfil ou serviço."},{"tipo":"h2","texto":"149. RECLAMAÇÕES SOBRE RANKING"},{"tipo":"p","c":"Um Host ou Prestador poderá contactar a Venue1Hub quando considere existir:"},{"tipo":"p","c":"a) erro técnico;"},{"tipo":"p","c":"b) informação incorreta;"},{"tipo":"p","c":"c) suspensão indevida;"},{"tipo":"p","c":"d) outro problema relacionado com a sua visibilidade."},{"tipo":"h2","texto":"150. NÃO EXISTE DIREITO A REVISÃO MANUAL DE CADA POSIÇÃO"},{"tipo":"p","c":"O facto de um Listing aparecer numa posição inferior à esperada não cria automaticamente direito a revisão individual ou reposicionamento."},{"tipo":"h2","texto":"151. ERROS TÉCNICOS"},{"tipo":"p","c":"Problemas técnicos genuínos poderão ser investigados."},{"tipo":"h2","texto":"152. LISTING QUE NÃO APARECE"},{"tipo":"p","c":"Antes de contactar suporte, o Host poderá verificar:"},{"tipo":"p","c":"a) se o Listing está publicado;"},{"tipo":"p","c":"b) disponibilidade;"},{"tipo":"p","c":"c) filtros;"},{"tipo":"p","c":"d) localização;"},{"tipo":"p","c":"e) estado da Conta;"},{"tipo":"p","c":"f) eventuais restrições."},{"tipo":"h2","texto":"153. CONTACTOS"},{"tipo":"p","c":"Questões relacionadas com ranking ou recomendações poderão ser dirigidas para:"},{"tipo":"p","c":[{"t":"mail@venue1hub.com","b":true}]},{"tipo":"h2","texto":"154. INFORMAÇÃO ÚTIL NUM PEDIDO"},{"tipo":"p","c":"Quando possível, o utilizador deverá indicar:"},{"tipo":"p","c":"a) Listing ID;"},{"tipo":"p","c":"b) pesquisa realizada;"},{"tipo":"p","c":"c) filtros;"},{"tipo":"p","c":"d) localização;"},{"tipo":"p","c":"e) data;"},{"tipo":"p","c":"f) descrição do problema;"},{"tipo":"p","c":"g) screenshot, quando útil."},{"tipo":"h2","texto":"155. TRANSPARÊNCIA NÃO SIGNIFICA GARANTIA DE EXPLICAÇÃO INDIVIDUAL COMPLETA"},{"tipo":"p","c":"A presente Política explica os principais parâmetros utilizados no sistema."},{"tipo":"p","c":"Não significa que a Venue1Hub tenha de revelar a fórmula técnica integral ou justificar matematicamente cada posição individual, salvo quando a legislação aplicável imponha obrigação diferente."},{"tipo":"h2","texto":"156. ALTERAÇÃO DE PREÇO PELO HOST"},{"tipo":"p","c":"Um Host é livre de ajustar o seu preço nos termos permitidos pela Plataforma."},{"tipo":"p","c":"Essa alteração poderá influenciar a correspondência com filtros e outros elementos do ranking."},{"tipo":"h2","texto":"157. ALTERAÇÃO DE DISPONIBILIDADE"},{"tipo":"p","c":"Abrir mais datas poderá aumentar o número de pesquisas em que o Listing é elegível."},{"tipo":"p","c":"Isto não significa necessariamente aumento da posição dentro de cada pesquisa."},{"tipo":"h2","texto":"158. BOAS REVIEWS"},{"tipo":"p","c":"Reviews positivas podem constituir um sinal relevante, mas não garantem determinada posição."},{"tipo":"h2","texto":"159. VOLUME DE RESERVAS"},{"tipo":"p","c":"Um histórico de Reservas poderá gerar sinais de performance, mas a Venue1Hub poderá procurar evitar um sistema que torne impossível a entrada de novos Listings apenas por falta de histórico."},{"tipo":"h2","texto":"160. DIVERSIDADE DE OFERTA"},{"tipo":"p","c":"A Venue1Hub poderá adotar mecanismos destinados a proporcionar variedade útil de resultados, quando adequado à experiência de pesquisa."},{"tipo":"h2","texto":"161. NÃO GARANTIA DE REPRESENTAÇÃO PROPORCIONAL"},{"tipo":"p","c":"A Plataforma não garante que todas as categorias, Hosts ou zonas tenham a mesma representação em cada conjunto de resultados."},{"tipo":"h2","texto":"162. RECOMENDAÇÕES EDITORIAIS"},{"tipo":"p","c":"A Venue1Hub poderá criar coleções ou seleções editoriais."},{"tipo":"h2","texto":"163. COLEÇÕES"},{"tipo":"p","c":"Exemplos:"},{"tipo":"p","c":"a) espaços para formação;"},{"tipo":"p","c":"b) espaços para eventos;"},{"tipo":"p","c":"c) estúdios;"},{"tipo":"p","c":"d) espaços recentemente adicionados;"},{"tipo":"p","c":"e) seleções temáticas."},{"tipo":"h2","texto":"164. CURADORIA EDITORIAL"},{"tipo":"p","c":"Quando uma seleção resulte de curadoria editorial e não de ranking automatizado, a Venue1Hub poderá identificar ou contextualizar essa natureza quando adequado."},{"tipo":"h2","texto":"165. PROMOÇÕES"},{"tipo":"p","c":"Campanhas promocionais poderão temporariamente aumentar a exposição de determinados Listings."},{"tipo":"h2","texto":"166. CONDIÇÕES DA CAMPANHA"},{"tipo":"p","c":"Quando isso ocorra, as regras aplicáveis deverão estar previstas nas condições da campanha ou produto."},{"tipo":"h2","texto":"167. FOUNDING HOSTS"},{"tipo":"p","c":"Se programas iniciais para Founding Hosts incluírem benefícios específicos de visibilidade, esses benefícios deverão ser definidos nas condições do programa."},{"tipo":"h2","texto":"168. NÃO PRESUMIR BENEFÍCIO NÃO CONTRATADO"},{"tipo":"p","c":"A participação num programa não implica influência no ranking se essa vantagem não estiver expressamente prevista."},{"tipo":"h2","texto":"169. MERCADOS DIFERENTES"},{"tipo":"p","c":"Os parâmetros principais poderão manter-se semelhantes entre mercados, mas a respetiva importância poderá variar em função:"},{"tipo":"p","c":"a) da oferta disponível;"},{"tipo":"p","c":"b) do comportamento de pesquisa;"},{"tipo":"p","c":"c) das funcionalidades locais;"},{"tipo":"p","c":"d) das regras legais."},{"tipo":"h2","texto":"170. EXPANSÃO INTERNACIONAL"},{"tipo":"p","c":"A Venue1Hub poderá adaptar esta Política à legislação aplicável nos diferentes mercados em que opere."},{"tipo":"h2","texto":"171. DSA"},{"tipo":"p","c":"Quando as obrigações aplicáveis à Venue1Hub ao abrigo do Digital Services Act incluam transparência de sistemas de recomendação, a Plataforma deverá disponibilizar informação clara sobre os principais parâmetros utilizados e as opções disponíveis ao utilizador para os influenciar."},{"tipo":"h2","texto":"172. REGULAMENTO P2B"},{"tipo":"p","c":"Quando aplicável à relação com Business Hosts ou Prestadores, a Venue1Hub deverá assegurar a transparência necessária relativamente aos principais parâmetros que determinam o ranking e à respetiva importância relativa."},{"tipo":"h2","texto":"173. PAGAMENTO COMO FATOR DE RANKING"},{"tipo":"p","c":"Quando Business Hosts ou Prestadores possam influenciar ranking ou visibilidade mediante pagamento direto ou indireto, essa possibilidade deverá ser descrita de forma adequada."},{"tipo":"h2","texto":"174. CONDIÇÕES COMERCIAIS DIFERENCIADAS"},{"tipo":"p","c":"Condições Enterprise ou outras condições negociadas poderão incluir produtos comerciais específicos, desde que sejam compatíveis com a legislação e devidamente documentados."},{"tipo":"h2","texto":"175. NÃO EXIGÊNCIA DE DIVULGAÇÃO DE SEGREDOS COMERCIAIS"},{"tipo":"p","c":"A transparência sobre os parâmetros principais não exige a divulgação de detalhes cuja revelação permita enganar, manipular ou causar dano material ao sistema, na medida permitida pela legislação aplicável."},{"tipo":"h2","texto":"176. DOCUMENTAÇÃO DE PUBLICIDADE"},{"tipo":"p","c":"A Venue1Hub deverá manter documentação interna adequada sobre publicidade e influência comercial no ranking."},{"tipo":"h2","texto":"177. INFORMAÇÃO DO ANUNCIANTE"},{"tipo":"p","c":"Quando legalmente exigido, os utilizadores deverão conseguir identificar a natureza publicitária de determinado conteúdo e obter a informação relevante associada."},{"tipo":"h2","texto":"178. RELAÇÃO COM OS TERMOS DE SPONSORED LISTINGS"},{"tipo":"p","c":"Os Termos de Publicidade / Sponsored Listings deverão definir especificamente:"},{"tipo":"p","c":"a) quem pode anunciar;"},{"tipo":"p","c":"b) como funciona o produto;"},{"tipo":"p","c":"c) preço;"},{"tipo":"p","c":"d) duração;"},{"tipo":"p","c":"e) posicionamento;"},{"tipo":"p","c":"f) identificação;"},{"tipo":"p","c":"g) métricas;"},{"tipo":"p","c":"h) cancelamento;"},{"tipo":"p","c":"i) limitações."},{"tipo":"h2","texto":"179. NÃO PROMESSA DE CLIQUES OU CONVERSÕES"},{"tipo":"p","c":"Publicidade e ranking patrocinado não constituem garantia de performance comercial."},{"tipo":"h2","texto":"180. RELAÇÃO COM REVIEWS"},{"tipo":"p","c":"As avaliações utilizadas como sinal de ranking deverão ser tratadas de acordo com a Política de Avaliações e Reviews."},{"tipo":"h2","texto":"181. RELAÇÃO COM LISTINGS"},{"tipo":"p","c":"A elegibilidade dos Listings continua sujeita à Política de Anúncios / Listings."},{"tipo":"h2","texto":"182. RELAÇÃO COM TRUST & SAFETY"},{"tipo":"p","c":"A Venue1Hub poderá limitar a recomendação ou visibilidade de conteúdo quando isso seja necessário por razões legítimas de segurança, fraude ou integridade."},{"tipo":"h2","texto":"183. RELAÇÃO COM SUSPENSÃO"},{"tipo":"p","c":"Listings ou Contas suspensos poderão deixar de participar nos resultados durante a medida aplicável."},{"tipo":"h2","texto":"184. RELAÇÃO COM ACESSIBILIDADE"},{"tipo":"p","c":"Filtros de acessibilidade poderão alterar o conjunto de resultados elegíveis nos termos da Política de Acessibilidade."},{"tipo":"h2","texto":"185. RELAÇÃO COM SUBSCRIÇÕES"},{"tipo":"p","c":"Qualquer vantagem de visibilidade associada a planos pagos deverá ser consistente com os Termos de Subscrição."},{"tipo":"h2","texto":"186. RELAÇÃO COM PUBLICIDADE"},{"tipo":"p","c":"Qualquer influência derivada especificamente de compra de publicidade será tratada também nos Termos de Publicidade / Sponsored Listings."},{"tipo":"h2","texto":"187. ALTERAÇÕES A ESTA POLÍTICA"},{"tipo":"p","c":"A Venue1Hub poderá alterar esta Política para refletir:"},{"tipo":"p","c":"a) novos parâmetros;"},{"tipo":"p","c":"b) novos filtros;"},{"tipo":"p","c":"c) alterações do algoritmo;"},{"tipo":"p","c":"d) personalização;"},{"tipo":"p","c":"e) IA;"},{"tipo":"p","c":"f) publicidade;"},{"tipo":"p","c":"g) subscrições;"},{"tipo":"p","c":"h) novos mercados;"},{"tipo":"p","c":"i) alterações legais."},{"tipo":"h2","texto":"188. ATUALIZAÇÃO QUANDO O PRODUTO MUDAR"},{"tipo":"p","c":"Uma alteração material no funcionamento das recomendações deverá ser acompanhada, quando adequado, pela atualização desta Política."},{"tipo":"h2","texto":"189. VERSIONAMENTO"},{"tipo":"p","c":"A Venue1Hub deverá manter registo das versões desta Política."},{"tipo":"h2","texto":"190. PRINCÍPIO DE CORRESPONDÊNCIA COM O PRODUTO REAL"},{"tipo":"p","c":"Esta Política deverá descrever aquilo que a Plataforma efetivamente faz."},{"tipo":"p","c":"Não deverão permanecer publicadas referências a parâmetros ou funcionalidades que:"},{"tipo":"p","c":"a) nunca tenham sido implementados;"},{"tipo":"p","c":"b) tenham sido descontinuados;"},{"tipo":"p","c":"c) funcionem de forma materialmente diferente da descrição pública."},{"tipo":"h2","texto":"191. CHECKLIST INTERNO ANTES DE ALTERAR O RANKING"},{"tipo":"p","c":"Antes de uma alteração material, a Venue1Hub deverá considerar:"},{"tipo":"p","c":"☐ Qual é o objetivo da alteração?"},{"tipo":"p","c":"☐ Quais são os principais parâmetros?"},{"tipo":"p","c":"☐ Alterou-se a importância relativa dos parâmetros?"},{"tipo":"p","c":"☐ Existe influência de pagamento?"},{"tipo":"p","c":"☐ Existe publicidade?"},{"tipo":"p","c":"☐ Existe personalização?"},{"tipo":"p","c":"☐ São utilizados dados pessoais?"},{"tipo":"p","c":"☐ Existem novos riscos de manipulação?"},{"tipo":"p","c":"☐ Existe impacto sobre Business Hosts?"},{"tipo":"p","c":"☐ Esta Política precisa de ser atualizada?"},{"tipo":"p","c":"☐ Os Termos precisam de ser atualizados?"},{"tipo":"p","c":"☐ A documentação interna foi atualizada?"},{"tipo":"h2","texto":"192. DOCUMENTAÇÃO INTERNA RECOMENDADA"},{"tipo":"p","c":"A documentação de ranking poderá incluir:"},{"tipo":"lista","chave":"4","itens":[{"n":0,"c":"Ranking Version ID;"},{"n":0,"c":"data de entrada em produção;"},{"n":0,"c":"responsável;"},{"n":0,"c":"finalidade;"},{"n":0,"c":"superfícies onde é utilizado;"},{"n":0,"c":"principais parâmetros;"},{"n":0,"c":"importância relativa;"},{"n":0,"c":"filtros;"},{"n":0,"c":"critérios de elegibilidade;"},{"n":0,"c":"efeito da disponibilidade;"},{"n":0,"c":"efeito das reviews;"},{"n":0,"c":"efeito da performance;"},{"n":0,"c":"efeito de subscrições;"},{"n":0,"c":"efeito de publicidade;"},{"n":0,"c":"personalização;"},{"n":0,"c":"dados utilizados;"},{"n":0,"c":"sistemas automatizados envolvidos;"},{"n":0,"c":"regras antifraude;"},{"n":0,"c":"histórico de alterações;"},{"n":0,"c":"testes;"},{"n":0,"c":"aprovação;"},{"n":0,"c":"versão pública correspondente."}]},{"tipo":"h2","texto":"193. EXEMPLO SIMPLIFICADO — PESQUISA PADRÃO"},{"tipo":"p","c":"Um utilizador procura:"},{"tipo":"p","c":[{"t":"Sala de reunião em Lisboa para 10 pessoas amanhã às 14h00.","b":true}]},{"tipo":"p","c":"A Venue1Hub poderá primeiro determinar quais os Listings que correspondem a:"},{"tipo":"p","c":[{"t":"Localização\n","b":true},{"t":"→ Lisboa / área relevante."}]},{"tipo":"p","c":[{"t":"Capacidade\n","b":true},{"t":"→ pelo menos 10 pessoas."}]},{"tipo":"p","c":[{"t":"Disponibilidade\n","b":true},{"t":"→ amanhã às 14h00."}]},{"tipo":"p","c":[{"t":"Categoria / utilização\n","b":true},{"t":"→ adequada a reunião."}]},{"tipo":"p","c":"Depois, entre os resultados elegíveis, poderão ser considerados fatores como:"},{"tipo":"p","c":[{"t":"qualidade + reviews + preço + performance + relevância adicional.","b":true}]},{"tipo":"p","c":"Caso exista resultado patrocinado elegível, este poderá receber visibilidade específica, mas deverá ser identificado como patrocinado."},{"tipo":"h2","texto":"194. EXEMPLO — ORDENAÇÃO POR PREÇO"},{"tipo":"p","c":"Se o mesmo utilizador selecionar:"},{"tipo":"p","c":[{"t":"“Preço: mais baixo primeiro”","b":true}]},{"tipo":"p","c":"o preço poderá tornar-se o principal critério de ordenação entre os resultados elegíveis."},{"tipo":"h2","texto":"195. EXEMPLO — FILTRO DE ACESSIBILIDADE"},{"tipo":"p","c":"Se o utilizador adicionar:"},{"tipo":"p","c":[{"t":"“Entrada sem degraus”","b":true}]},{"tipo":"p","c":"Listings que não possuam essa característica poderão ser removidos do conjunto de resultados apresentado."},{"tipo":"h2","texto":"196. EXEMPLO — RESULTADO PATROCINADO"},{"tipo":"p","c":"Um Host poderá contratar um Sponsored Listing."},{"tipo":"p","c":"Se esse Listing for apresentado com visibilidade adicional em resultado do pagamento, deverá ser identificado como:"},{"tipo":"p","c":[{"t":"Patrocinado","b":true}]},{"tipo":"p","c":"ou expressão equivalente."},{"tipo":"h2","texto":"197. EXEMPLO — PLANO PRO"},{"tipo":"p","c":"Se o Plano Pro incluir contratualmente maior visibilidade, esse benefício poderá influenciar determinadas oportunidades de exposição."},{"tipo":"p","c":"Isso não significa:"},{"tipo":"p","c":"a) primeira posição garantida;"},{"tipo":"p","c":"b) prioridade sobre filtros incompatíveis;"},{"tipo":"p","c":"c) possibilidade de aparecer quando indisponível;"},{"tipo":"p","c":"d) possibilidade de contornar medidas de segurança;"},{"tipo":"p","c":"e) Reserva garantida."},{"tipo":"h2","texto":"198. RECONHECIMENTO DO HOST / PRESTADOR"},{"tipo":"p","c":"Ao utilizar a Venue1Hub como Host ou Prestador, reconhece que:"},{"tipo":"p","c":"☐ A posição dos resultados pode variar."},{"tipo":"p","c":"☐ Não existe direito permanente a uma posição específica."},{"tipo":"p","c":"☐ Relevância, disponibilidade, localização, preço, reviews, qualidade, performance e outros fatores podem influenciar o ranking."},{"tipo":"p","c":"☐ A correspondência com filtros do Cliente pode ser determinante."},{"tipo":"p","c":"☐ Uma subscrição paga pode incluir vantagens de visibilidade quando expressamente previsto."},{"tipo":"p","c":"☐ Publicidade ou Sponsored Listings serão tratados como mecanismos comerciais próprios."},{"tipo":"p","c":"☐ Resultados patrocinados deverão ser identificados."},{"tipo":"p","c":"☐ Reviews falsas, Reservas fictícias ou outras formas de manipulação são proibidas."},{"tipo":"p","c":"☐ A Venue1Hub pode alterar os mecanismos de ranking para melhorar a Plataforma."},{"tipo":"p","c":"☐ Alterações materiais serão refletidas na informação pública quando aplicável."},{"tipo":"h2","texto":"199. RECONHECIMENTO DO CLIENTE"},{"tipo":"p","c":"Ao utilizar as funcionalidades de pesquisa e recomendação, o Cliente reconhece que:"},{"tipo":"p","c":"☐ A ordem dos resultados não representa necessariamente uma avaliação absoluta de qualidade."},{"tipo":"p","c":"☐ A primeira posição não significa necessariamente “melhor Espaço” para todas as pessoas."},{"tipo":"p","c":"☐ Os resultados podem depender da pesquisa, localização, data, filtros, disponibilidade e outros parâmetros."},{"tipo":"p","c":"☐ Pode alterar os resultados através dos filtros e opções de ordenação disponíveis."},{"tipo":"p","c":"☐ Determinados resultados poderão ser patrocinados e, nesse caso, deverão ser identificados."},{"tipo":"p","c":"☐ As recomendações destinam-se a facilitar a descoberta e não substituem a análise das características do Listing antes da Reserva."},{"tipo":"h2","texto":"200. CONTACTOS"},{"tipo":"p","c":"Para questões relacionadas com ranking, recomendações ou visibilidade na Venue1Hub:"},{"tipo":"p","c":[{"t":"EdgeHub OÜ — Venue1Hub®\n","b":true},{"t":"E-mail: "},{"t":"mail@venue1hub.com\n","b":true},{"t":"Website:"},{"t":" www.venue1hub.com\n","href":"http://www.venue1hub.com/"},{"t":"Sede: Tallinn, Estónia"}]},{"tipo":"p","c":[{"t":"Hosts ou Prestadores que comuniquem um problema relacionado com um Listing específico deverão, sempre que possível, indicar o respetivo "},{"t":"Listing ID ou Provider ID","b":true},{"t":" e informação suficiente para permitir a análise."}]},{"tipo":"p","c":[{"t":"VERSÃO 1.0 — 14-09-2026","b":true}]},{"tipo":"p","c":[{"t":"EdgeHub OÜ — Venue1Hub®","b":true}]}]};
